From bf3f098987651513a269a07447303de716b8d16b Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 17:09:50 +0100
Subject: [PATCH] containments/desktop: anchor the drag image where the icon
 was pressed

The drag hotspot used the pointer position at the moment the drag began,
so if the pointer moved quickly before that, the icon was dragged away
from the pointer and dropped there. Use the press position instead.

BUG: 527529
---
 containments/desktop/package/contents/ui/FolderView.qml | 2 +-
 1 file changed, 1 insertion(+), 1 deletion(-)

diff --git a/containments/desktop/package/contents/ui/FolderView.qml b/containments/desktop/package/contents/ui/FolderView.qml
index b858d16f7a..5a4c5a9613 100644
--- a/containments/desktop/package/contents/ui/FolderView.qml
+++ b/containments/desktop/package/contents/ui/FolderView.qml
@@ -487,7 +487,7 @@ FocusScope {
                     }
                     pressedItem.hideToolTip();
                     gridView.verticalDropHitscanOffset = pressedItem.iconArea.y + (pressedItem.iconArea.height / 2);
-                    dir.dragSelected(mouse.x, mouse.y);
+                    dir.dragSelected(pressX, pressY);
                     clearPressState();
                 } else {
                     // Disable rubberband in popup list view mode or while renaming
-- 
